)

mapper.select:
SELECT account_no, balance, updated_at
FROM accounts
WHERE account_no = #{accountNo}

mapper.update:
UPDATE accounts
SET balance = balance - #{amount},
updated_at = NOW()
WHERE account_no = #{accountNo}
AND balance >= #{amount}
